func RedirectHostEqualFold(v string) predicate.CSPScan {
	return predicate.CSPScan(sql.FieldEqualFold(FieldRedirectHost, v))
}

// RedirectHostContainsFold applies the ContainsFold predicate on the "redirect_host" field.
func RedirectHostContainsFold(v string) predicate.CSPScan {
	return predicate.CSPScan(sql.FieldContainsFold(FieldRedirectHost, v))
}

// HasTarget applies the HasEdge predicate on the "target" edge.
func HasTarget() predicate.CSPScan {
	return predicate.CSPScan(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, TargetTable, TargetColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasTargetWith applies the HasEdge predicate on the "target" edge with a given conditions (other predicates).
func HasTargetWith(preds ...predicate.Target) predicate.CSPScan {
	return predicate.CSPScan(func(s *sql.Selector) {
		step := newTargetStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CSPScan) predicate.CSPScan {
	return predicate.CSPScan(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CSPScan) predicate.CSPScan {
	return predicate.CSPScan(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CSPScan) predicate.CSPScan {
	return predicate.CSPScan(sql.NotPredicates(p))
}
